import { useEffect, useState } from "react"
import { cn } from "@/components/ui/cn.ts"

type Toast = { id: number; text: string; kind: "ok" | "error" }
let next = 1
const listeners = new Set<(t: Toast) => void>()

/** Shows a notice for a few seconds. */
export function toast(text: string, kind: Toast["kind"] = "ok"): void {
  const t = { id: next++, text, kind }
  for (const l of listeners) l(t)
}

export function Toaster() {
  const [toasts, setToasts] = useState<Toast[]>([])
  useEffect(() => {
    const add = (t: Toast) => {
      setToasts((all) => [...all, t])
      setTimeout(() => setToasts((all) => all.filter((x) => x.id !== t.id)), 4000)
    }
    listeners.add(add)
    return () => void listeners.delete(add)
  }, [])
  return (
    <div className="fixed right-4 bottom-4 z-50 flex flex-col gap-2" role="status" aria-live="polite">
      {toasts.map((t) => (
        <div
          key={t.id}
          className={cn(
            "rounded-md px-4 py-2 text-sm shadow-lg",
            t.kind === "ok" ? "bg-foreground text-background" : "bg-destructive text-white",
          )}
        >
          {t.text}
        </div>
      ))}
    </div>
  )
}
